/** Voz | Texto, como dos segmentos con ícono (antes: 🎤 ↔ ⌨️). */
export function SelectorModo({ modo, onCambiar }: { modo: "voice" | "text"; onCambiar: () => void }) {
  const seg = (activo: boolean): CSSProperties => ({
    height: 34,
    padding: "0 12px",
    border: "none",
    borderRadius: 9,
    display: "flex",
    alignItems: "center",
    gap: 6,
