/**
 * El micrófono: te toca (naranja con volumen, invita sin gritar), grabando (rojo con el cuadro, el anillo
 * sigue tu voz de verdad) o apagado (mientras habla el cliente o se piensa la respuesta).
 */
export function BotonMicrofono({
  estado,
  nivelVoz,
  etiqueta,
  onClick,
}: {
  estado: "te_toca" | "grabando" | "apagado";
  nivelVoz: number;
  etiqueta: string;
  onClick: () => void;
}) {
  // 151-C: al tocar para enviar, el micrófono pasaba de rojo a naranja un instante antes de apagarse
  // (entre que se cierra tu turno y empieza a pensar el cliente). Al salir de «grabando», el naranja
  // espera 400 ms: si en ese tiempo el cliente empieza, se va directo a apagado.
  const [retener, setRetener] = useState(false);
  const [anterior, setAnterior] = useState(estado);
  if (anterior !== estado) {
    setAnterior(estado);
    if (anterior === "grabando" && estado === "te_toca") setRetener(true);
    else if (estado !== "te_toca") setRetener(false);
  }
  useEffect(() => {
    if (!retener) return;
    const t = setTimeout(() => setRetener(false), 400);
    return () => clearTimeout(t);
  }, [retener]);
  const visible = retener && estado === "te_toca" ? "apagado" : estado;
  const grabando = visible === "grabando";
  const toca = visible === "te_toca";
  const fondo: CSSProperties = grabando
    ? { background: "var(--c-danger)" }
    : toca
      ? {
          background: "linear-gradient(180deg, var(--c-play-claro) 0%, var(--c-play-centro) 50%, var(--c-play-hondo) 100%)",
          boxShadow: "inset 0 -3px 0 rgb(var(--c-play-sombra-rgb) / 0.35), inset 0 2px 0 rgba(255,255,255,0.25)",
        }
      : { background: "var(--c-disabled-bg)" };
  return (
    <div style={{ position: "relative", width: 84, height: 84, margin: "6px 0" }}>
      <div
        aria-hidden
        style={{
          position: "absolute",
          inset: -12,
          borderRadius: "50%",
          border: "2px solid rgb(var(--c-danger-rgb) / 0.45)",
          opacity: grabando ? 1 : 0,
          transform: `scale(${1 + Math.min(1, nivelVoz * 1.4) * 0.22})`,
          transition: "opacity 200ms ease, transform 90ms linear",
          pointerEvents: "none",
        }}
      />
      <button
        type="button"
        onClick={onClick}
        disabled={visible === "apagado"}
        aria-label={etiqueta}
        className={toca ? "practica-mic-invita" : undefined}
        style={{
          position: "relative",
          width: 84,
          height: 84,
          borderRadius: "50%",
          border: "none",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          cursor: visible === "apagado" ? "default" : "pointer",
          transition: "background 200ms ease",
          WebkitTapHighlightColor: "transparent",
          padding: 0,
          ...fondo,
        }}
      >
        {grabando ? (
          <span style={{ width: 24, height: 24, borderRadius: 6, background: "#FFFFFF", display: "block" }} />
        ) : (
          <IconoMicrofono tam={34} color={toca ? "#FFFFFF" : "var(--c-disabled-text)"} />
        )}
      </button>
    </div>
  );
}

