              whiteSpace: "pre-wrap",
              wordBreak: "break-word",
              ...(t.esTuyo
                ? { background: "var(--c-elevated)", color: "var(--c-text)", borderTopRightRadius: 6 }
                : { background: "var(--c-surface)", border: "1px solid var(--c-border)", color: "var(--c-text-soft)", borderTopLeftRadius: 6 }),
            }}
          >
            {t.texto}
          </div>
        </div>
      ))}
    </div>
  );
}

